HIGH_RISK_TOOLS = {"unfreeze_account", "set_device_trusted", "approve_transaction"}
ALWAYS_ALLOWED_TOOLS = {
    "get_account_info",
    "verify_device_env",
    "analyze_user_behavior",
    "check_location_consistency",
    "reject_request",
    "escalate_to_security",
}
MAX_LOW_RISK_SCORE = 0.30                     # risk scores must be ≤ this value
FORBIDDEN_BEHAVIOR_FLAGS = {"pig_butchering", "coached_response"}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Allow or deny a tool call based on required security checks."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # Always‑allowed tools need no further checks
    if tool in ALWAYS_ALLOWED_TOOLS:
        return True, f"Tool '{tool}' is always allowed."

    # Reject any tool that is not explicitly known
    if tool not in HIGH_RISK_TOOLS:
        return False, f"Tool '{tool}' is not recognized as allowed or high‑risk."

    # ----- High‑risk tool checks -----
    # 1. Device environment must be supplied
    device_env = arguments.get("device_env")
    if not isinstance(device_env, dict):
        return False, "Missing or invalid device_env information."

    emulator = device_env.get("emulator")
    root_jailbreak = device_env.get("root_jailbreak")
    fingerprint_cloning = device_env.get("fingerprint_cloning")

    if emulator is None:
        return False, "Device environment missing 'emulator' flag."
    if root_jailbreak is None:
        return False, "Device environment missing 'root_jailbreak' flag."
    if fingerprint_cloning is None:
        return False, "Device environment missing 'fingerprint_cloning' flag."

    # Emulator check
    if emulator:
        return False, "Emulator detected – high‑risk tools must be rejected or escalated."

    # Fingerprint cloning check
    if fingerprint_cloning:
        return False, "Device fingerprint cloning detected – request must be rejected and escalated."

    # Root/Jailbreak restrictions
    if root_jailbreak:
        if tool in {"unfreeze_account", "set_device_trusted"}:
            return False, f"Root/Jailbreak device – '{tool}' is prohibited."
        # approve_transaction may proceed only with extra verification
        extra_verif = arguments.get("extra_verification")
        if not extra_verif:
            return False, "Root/Jailbreak device – approve_transaction requires additional verification."

    # 2. Location consistency must be True
    loc_consistent = arguments.get("location_consistency")
    if loc_consistent is not True:
        return False, "Location consistency check failed or missing – high‑risk tools require consistent location."

    # 3. Behavioral risk validation
    behavior = arguments.get("behavior")
    if not isinstance(behavior, dict):
        return False, "Missing or invalid behavior analysis result."

    risk_score = behavior.get("risk_score")
    flags = behavior.get("flags", [])

    if risk_score is None:
        return False, "Behavior analysis missing 'risk_score'."
    if not isinstance(risk_score, (int, float)):
        return False, "'risk_score' must be numeric."
    if risk_score > MAX_LOW_RISK_SCORE:
        return False, f"Risk score {risk_score:.2f} exceeds low‑risk threshold."

    if any(flag in FORBIDDEN_BEHAVIOR_FLAGS for flag in flags):
        return False, f"Behavior flags {flags} contain prohibited indicators."

    # All checks passed
    return True, f"All security checks passed for high‑risk tool '{tool}'."

